/**
 * Application type aliases derived from the auto-generated OpenAPI types.
 *
 * The generated file (`api-types.generated.ts`) is produced by running:
 *   npm run codegen:api-types  (in frontend/)
 * which calls openapi-typescript against the backend OpenAPI spec and writes
 * the result to src/lib/api-types.generated.ts.
 *
 * Rather than hand-writing types, we derive them here from
 * `components["schemas"]` in the generated file. This means any drift between
 * the backend spec and these types will be caught by the TypeScript compiler.
 *
 * For types that are not yet in the generated spec, a TODO comment is added.
 */
import type { components } from "@/lib/api-types.generated";

// ---------------------------------------------------------------------------
// User
// ---------------------------------------------------------------------------

/**
 * User as returned by the backend API (/v1/users endpoints).
 * Derived from components["schemas"]["User"].
 * The generated schema marks createdAt/updatedAt optional; we keep them
 * required here to preserve backwards-compatibility with existing call sites.
 */
export type BackendUser = Required<Pick<components["schemas"]["User"], "id" | "publicKey">> &
  Pick<components["schemas"]["User"], "createdAt" | "updatedAt">;

// ---------------------------------------------------------------------------
// Stream events
// ---------------------------------------------------------------------------

/**
 * The union of all known stream event type strings.
 *
 * The generated spec defines 8 event types. FEE_CONFIG_UPDATED and
 * ADMIN_TRANSFERRED are emitted by the contract but not yet documented in the
 * OpenAPI spec.
 * TODO: add FEE_CONFIG_UPDATED and ADMIN_TRANSFERRED to the backend OpenAPI spec,
 * then replace this hand-written union with:
 *   export type StreamEventType = components["schemas"]["StreamEvent"]["eventType"];
 */
export type StreamEventType =
  | components["schemas"]["StreamEvent"]["eventType"]
  | "FEE_CONFIG_UPDATED"
  | "ADMIN_TRANSFERRED";

/**
 * A single stream event as returned by the backend API.
 * Derived from components["schemas"]["StreamEvent"].
 *
 * Notes on differences from the generated schema:
 * - `amount` is `string | null` here (was already optional+null in spec).
 * - `createdAt` is kept required (spec marks it optional).
 * - `eventType` is widened to `StreamEventType` to include the two extra
 *   event types not yet in the spec (FEE_CONFIG_UPDATED, ADMIN_TRANSFERRED).
 */
export interface BackendStreamEvent
  extends Omit<components["schemas"]["StreamEvent"], "eventType" | "amount" | "createdAt"> {
  eventType: StreamEventType;
  amount: string | null;
  createdAt: string;
}

// ---------------------------------------------------------------------------
// Stream
// ---------------------------------------------------------------------------

/**
 * A payment stream record as returned by the backend API.
 * Derived from components["schemas"]["Stream"].
 *
 * Notes on differences from the generated schema:
 * - Several fields the spec marks optional are kept required here because
 *   the application logic relies on them always being present in responses.
 *   TODO: align the spec to mark these required, then simplify this type.
 * - `senderUser` / `recipientUser` and `events` are not yet in the spec.
 *   TODO: add them to the OpenAPI spec.
 */
export interface BackendStream
  extends Omit<
    components["schemas"]["Stream"],
    | "depositedAmount"
    | "withdrawnAmount"
    | "startTime"
    | "lastUpdateTime"
    | "isActive"
    | "isPaused"
    | "createdAt"
    | "updatedAt"
  > {
  // Fields that the spec marks optional but the app requires:
  depositedAmount: string;
  withdrawnAmount: string;
  startTime: number;
  lastUpdateTime: number;
  isActive: boolean;
  isPaused?: boolean;
  createdAt: string;
  updatedAt: string;
  // TODO: add senderUser, recipientUser, and events to the OpenAPI spec.
  senderUser?: BackendUser;
  recipientUser?: BackendUser;
  events?: BackendStreamEvent[];
}

// ---------------------------------------------------------------------------
// Recurring payment schedules
// ---------------------------------------------------------------------------

/**
 * Lifecycle status of a recurring payment schedule.
 *
 * TODO: add `ScheduleStatus` to the backend OpenAPI spec, then replace this
 * hand-written union with:
 *   export type ScheduleStatus = components["schemas"]["ScheduleStatus"];
 */
export type ScheduleStatus =
  | "active"
  | "paused"
  | "cancelled"
  | "missed"
  | "insufficient_funds";

/**
 * Status of an individual run generated by a recurring schedule.
 *
 * TODO: add `ScheduleRunStatus` to the backend OpenAPI spec, then replace this
 * hand-written union with:
 *   export type ScheduleRunStatus = components["schemas"]["ScheduleRunStatus"];
 */
export type ScheduleRunStatus =
  | "scheduled"
  | "executed"
  | "missed"
  | "insufficient_funds"
  | "cancelled";

/**
 * A recurring payment schedule as returned by the backend API.
 *
 * Each executed run materialises a separate payment stream (see
 * `ScheduleRun.streamId`), so every generated stream is its own payment
 * obligation.
 *
 * TODO: add `RecurringSchedule` to the backend OpenAPI spec and derive this
 * type from components["schemas"]["RecurringSchedule"]. Until then the shape
 * is hand-written to match the planned API contract.
 */
export interface RecurringSchedule {
  /** Stable schedule identifier. */
  id: string;
  /** Public key of the wallet that owns (funds) the schedule. */
  owner: string;
  /** Public key of the wallet receiving each generated stream. */
  recipient: string;
  /** Token / asset identifier used for every run. */
  token: string;
  /** Amount transferred per run, as a decimal string. */
  amount: string;
  /** Cadence between runs, in seconds. */
  cadence: number;
  /** ISO-8601 timestamp of the next scheduled run. */
  nextRunAt: string;
  /** Current lifecycle status of the schedule. */
  status: ScheduleStatus;
  /**
   * Amount that must be available to fund the next run, as a decimal string.
   * TODO: confirm whether the backend returns this per-schedule or only via
   * the funding preview endpoint.
   */
  fundingRequirement: string;
  /** Chain/network identifier the schedule is bound to. */
  networkId: string;
}

/**
 * A single run generated by a recurring payment schedule.
 *
 * TODO: add `ScheduleRun` to the backend OpenAPI spec and derive this type
 * from components["schemas"]["ScheduleRun"].
 */
export interface ScheduleRun {
  /** Stable run identifier. */
  runId: string;
  /** ISO-8601 timestamp the run was scheduled for. */
  scheduledAt: string;
  /**
   * Identifier of the stream created by this run, if it executed.
   * Null when the run has not executed (missed / insufficient funds).
   */
  streamId: string | null;
  /** Outcome status of this run. */
  status: ScheduleRunStatus;
  /** On-chain transaction hash, if the run was submitted. */
  txHash: string | null;
}

/**
 * Funding preview for a schedule's next run, returned before confirmation.
 *
 * TODO: add `FundingPreview` to the backend OpenAPI spec and derive this type
 * from components["schemas"]["FundingPreview"].
 */
export interface FundingPreview {
  /** Amount required to fund the next run, as a decimal string. */
  requiredAmount: string;
  /** Balance currently available to the schedule, as a decimal string. */
  availableBalance: string;
  /**
   * Shortfall between required and available amounts, as a decimal string.
   * "0" when the schedule is sufficiently funded.
   */
  shortfall: string;
  /** ISO-8601 timestamp of the next run this preview applies to. */
  nextRunAt: string;
}

// ---------------------------------------------------------------------------
// Operation-specific response types (derived from `paths`)
// ---------------------------------------------------------------------------

// Re-export generated component schemas for consumers that want direct access.
export type { components } from "@/lib/api-types.generated";
